import{A as e,C as t,D as n,L as r,N as i,_ as a,f as o,g as s,h as c,j as l,u,v as d,w as f}from"./index-DyqjxL9f.js";import{t as p}from"./PageTitle-CPMasN_Y.js";import{t as m}from"./NextPage-DFV0QgQA.js";import{t as h}from"./ArtPlate-C4QjZABR.js";var g=[{title:`Literature mirrors culture`,html:`Each work shows what its people valued most. Greece prized honor and cleverness, India prized dharma, medieval France prized feudal loyalty, and the Hebrew tradition wrestled with faith and justice.`},{title:`Heroism has many faces`,html:`Achilles is a hero of strength, Odysseus of wit, Rama of duty, Roland of loyalty, and Job of endurance. The <em>Panchatantra</em> even makes heroes of a mouse and a tortoise.`},{title:`Duty and desire collide`,html:`Rama gives up a throne for his father’s word, and Arjuna must fight his own family. The hardest choices are between two things we care about.`},{title:`Pride brings downfall`,html:`Achilles’ rage, Roland’s refusal to blow the horn, Duryodhana’s envy, Ravana’s desire, and Odysseus’ boast all lead to suffering.`},{title:`Suffering can bring wisdom`,html:`Job, Odysseus, the Pandavas, and Priam all pass through great loss. Faced honestly, suffering can deepen understanding and compassion.`},{title:`Stories travel`,html:`The <em>Panchatantra</em> crossed into Persia and Europe, the <em>Ramayana</em> became <em>Maharadia Lawana</em> in Mindanao, and Charlemagne’s knights inspired our <em>moro-moro</em> plays.`}],_={class:`lessons`},v=[`innerHTML`],y={__name:`LessonGrid`,setup(e){return(e,a)=>{let s=n(`reveal`);return t(),c(`div`,_,[(t(!0),c(u,null,f(i(g),e=>l((t(),c(`div`,{key:e.title,class:`lesson`},[o(`h3`,null,r(e.title),1),o(`p`,{innerHTML:e.html},null,8,v)])),[[s]])),128))])}}},b={head:[`Work`,`Tradition`,`Central figure`,`Main conflict`,`Core value`,`Lesson for today`],rows:[[`Voice out of the Whirlwind`,`Hebrew`,`Job`,`A righteous man versus unexplained suffering`,`Faith and humility`,`We may not understand our trials, but we can endure them.`],[`The Panchatantra`,`Indian`,`Vishnu Sharma and his animals`,`Wisdom versus foolishness and deceit`,`Practical wisdom`,`Think before acting, and choose friends carefully.`],[`The Ramayana`,`Indian`,`Rama`,`Righteousness versus pride and desire`,`Dharma`,`Keeping your word builds trust, even at great cost.`],[`The Mahabharata`,`Indian`,`Arjuna and the Pandavas`,`Cousins at war over a kingdom`,`Duty without attachment`,`Do your best, and let go of what you cannot control.`],[`The Iliad`,`Greek`,`Achilles`,`Wounded pride in the middle of a war`,`Honor and glory`,`Anger hurts those closest to us, and compassion can heal.`],[`The Odyssey`,`Greek`,`Odysseus`,`A long journey home against gods and monsters`,`Cleverness and loyalty`,`Patience and wit can carry us through hardship.`],[`The Song of Roland`,`French`,`Roland`,`Loyal knights betrayed in battle`,`Feudal loyalty`,`Courage needs wisdom, and asking for help is not weakness.`]]},x={class:`subhead`,style:{"margin-bottom":`20px`}},S={class:`table-wrap`,tabindex:`0`,role:`region`,"aria-label":`Comparison of the seven works`},C={scope:`row`},w={__name:`ComparisonTable`,setup(e){return(e,s)=>{let d=n(`reveal`);return t(),c(u,null,[l((t(),c(`h3`,x,[...s[0]||=[a(`Comparing the seven works`,-1)]])),[[d]]),l((t(),c(`div`,S,[o(`table`,null,[o(`thead`,null,[o(`tr`,null,[(t(!0),c(u,null,f(i(b).head,e=>(t(),c(`th`,{key:e,scope:`col`},r(e),1))),128))])]),o(`tbody`,null,[(t(!0),c(u,null,f(i(b).rows,([e,...n])=>(t(),c(`tr`,{key:e},[o(`th`,C,r(e),1),(t(!0),c(u,null,f(n,(e,n)=>(t(),c(`td`,{key:n},r(e),1))),128))]))),128))])])])),[[d]])],64)}}},T={class:`feature`,style:{"margin-top":`clamp(56px, 8vw, 96px)`}},E={__name:`CraftNotes`,setup(e){return(e,r)=>{let i=n(`reveal`);return t(),c(`div`,T,[l((t(),c(`div`,null,[...r[0]||=[s(`<h3 style="font-size:1.8rem;">What I learned about literary craft</h3><p> Before this course, I read mainly for plot. Now I notice <em>how</em> a story is told. Many of these works began as <strong>oral literature</strong>, performed from memory long before they were written down. That explains Homer’s repeated epithets and the repeated laisses of <em>The Song of Roland</em>, which helped performers remember and listeners follow. </p><p> I learned to recognize techniques across cultures. The <strong>frame narrative</strong> appears in Job, the <em>Panchatantra</em>, and the <em>Mahabharata</em>. Beginning <strong>in medias res</strong> drives both Homeric epics. <strong>Divine intervention</strong> shapes nearly every work, from Athena guiding Odysseus to Krishna guiding Arjuna. </p><p> I also learned to read <strong>critically</strong>. Sita’s trial by fire and the portrayal of Muslims in <em>Roland</em> reflect attitudes we should question today. Appreciating a masterpiece does not mean accepting everything in it. </p>`,4)]])),[[i]]),l(d(h,{style:{"max-width":`380px`,"justify-self":`center`},src:`/assets/img/homer-bust.webp`,alt:`Marble bust of Homer as a bearded old man with blank eyes`,aspect:`3/4`,caption:`Bust of Homer, Roman copy of a Hellenistic original. The British Museum. Tradition says Homer was blind and composed his poems orally.`},null,512),[[i]])])}}},D={class:`page`},O={id:`main`},k={id:`learning`,class:`section`,"aria-labelledby":`page-title`},A={class:`wrap`},j={__name:`LearningView`,setup(n){return(n,r)=>(t(),c(`div`,D,[d(p,{label:`Summary of Learning`,prefix:`SUMMARY `,image:`/assets/img/homer-bust.webp`,after:`F`,suffix:` LEARNING`,"quote-source":`The Song of Roland, laisse 87`},{quote:e(()=>[...r[0]||=[a(`“Roland is fierce and Oliver is wise.”`,-1)]]),credit:e(()=>[...r[1]||=[a(` Pictures above: bust of Homer, The British Museum, and Achille-Etna Michallon, Landscape with the Death of Roland (sketch), c. 1819–22. `,-1)]]),default:e(()=>[r[2]||=a(` These seven works came from different places and centuries, yet they kept answering the same human questions. Here are the most important ideas I learned and how the works connect. `,-1)]),_:1}),o(`main`,O,[o(`section`,k,[o(`div`,A,[d(y),d(w),d(E)])]),d(m,{to:`/reflection`,title:`Personal Reflection`})])]))}};export{j as default};